-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/sandoria/Growing_Flowers.lua"]={["Path"]="scripts/quests/sandoria/Growing_Flowers.lua",["SHA256"]="7f103b9255c99dff3e0678fcd0fe4e1f3c9016edbe4e3a28436bf11b939a6f8a",["Text"]="-----------------------------------\n-- Growing Flowers\n-----------------------------------\n-- Log ID: 0, Quest ID: 58\n-- Kuu Mohzolhi : !pos -123 0 80 231\n-----------------------------------\nlocal northenSandoriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.GROWING_FLOWERS)\n\nquest.reward =\n{\n    fame     = 0,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nlocal flowerItems =\n{\n    xi.item.AMARYLLIS,\n    xi.item.ASPHODEL,\n    xi.item.CARNATION,\n    xi.item.CASABLANCA,\n    xi.item.CATTLEYA,\n    xi.item.CHAMOMILE,\n    xi.item.DAHLIA,\n    xi.item.FLAX_FLOWER,\n    xi.item.LILAC,\n    xi.item.LYCOPODIUM_FLOWER,\n    xi.item.MARGUERITE,\n    xi.item.OLIVE_FLOWER,\n    xi.item.PAPAKA_GRASS,\n    xi.item.PHALAENOPSIS,\n    xi.item.RAIN_LILY,\n    xi.item.RED_ROSE,\n    xi.item.SNOW_LILY,\n    xi.item.SWEET_WILLIAM,\n    xi.item.TAHRONGI_CACTUS,\n    xi.item.WATER_LILY,\n    xi.item.WIJNRUIT,\n}\n\nlocal function isTradeInTable(trade, itemTable)\n    for _, itemId in ipairs(itemTable) do\n        if npcUtil.tradeHasExactly(trade, itemId) then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Kuu_Mohzolhi'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.MARGUERITE) then\n                        return quest:progressEvent(605, 0, 231, 2)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(605, 0, 231, 1)\n                    else\n                        return quest:progressEvent(605, 0, 231, 0)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(605, 0, 231, 10),\n            },\n\n            onEventFinish =\n            {\n                [605] = function(player, csid, option, npc)\n                    -- Three possible event options are returned from the above triggers:\n                    -- 0    : Invalid Item was traded\n                    -- 1    : Valid Item was traded\n                    -- 10   : Cancel/Exit event option.\n                    -- 1002 : Marguerite was traded\n\n                    -- Correct trade option (Marguerite).\n                    if option == 1002 then\n                        if quest:complete(player) then\n                            player:confirmTrade()\n                            local mhflag = player:getMoghouseFlag()\n                            player:setMoghouseFlag(mhflag + 0x0001)\n                            player:messageSpecial(northenSandoriaID.text.MOGHOUSE_EXIT)\n                        end\n\n                    else\n                        -- Confirm trade if there was a trade.\n                        if option == 1 then\n                            player:confirmTrade()\n                        end\n\n                        -- Start quest if it wasn't.\n                        if player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_AVAILABLE then\n                            quest:begin(player)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Kuu_Mohzolhi'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- NOTE: After completing this quest, trade is not consumed.\n\n                    if npcUtil.tradeHasExactly(trade, xi.item.MARGUERITE) then\n                        return quest:progressEvent(605, 0, 231, 4)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(605, 0, 231, 5)\n                    else\n                        return quest:progressEvent(605, 0, 231, 0)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(605, 0, 231, 10),\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Her_Majestys_Garden.lua"]={["Path"]="scripts/quests/sandoria/Her_Majestys_Garden.lua",["SHA256"]="b58c2275e68d25996225d01c678e41b29e7eaccbfe5e33f1d9287c7a085a45ea",["Text"]="-----------------------------------\n-- Her Majestys Garden\n-----------------------------------\n-- Log ID: 0, Quest ID: 62\n-----------------------------------\n-- Chalvatot : !pos -105 0.1 72 233\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.HER_MAJESTYS_GARDEN)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.SANDORIA,\n    keyItem  = xi.keyItem.MAP_OF_THE_NORTHLANDS_AREA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 4\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Chalvatot'] = quest:progressEvent(84),\n\n            onEventFinish =\n            {\n                [84] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Chalvatot'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.CHUNK_OF_DERFLAND_HUMUS) then\n                        return quest:progressEvent(83)\n                    end\n                end,\n\n                onTrigger = quest:event(82),\n            },\n\n            onEventFinish =\n            {\n                [83] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Intermediate_Teamwork.lua"]={["Path"]="scripts/quests/sandoria/Intermediate_Teamwork.lua",["SHA256"]="74fc2f97f60d0c343d37fb3744674407a6c37bfc96754d620bc7fa2a3bc1ca41",["Text"]="-----------------------------------\n-- Intermediate Teamwork\n-----------------------------------\n-- Log ID: 0, Quest ID: 64\n-----------------------------------\n-- Vilatroire : !pos -260 -70 423 100\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.INTERMEDIATE_TEAMWORK)\n\nquest.reward =\n{\n    item     = xi.item.SCROLL_OF_MAGES_BALLAD,\n    fame     = 30,\n    fameArea = xi.fameArea.SANDORIA,\n    title    = xi.title.SECOND_RATE_ORGANIZER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.INTRODUCTION_TO_TEAMWORK) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getFameLevel(xi.fameArea.SANDORIA) >= 3 and\n                        player:getMainLvl() >= 10\n                    then\n                        return quest:progressEvent(133)\n                    else\n                        return quest:event(132):replaceDefault()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [133] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] =\n            {\n                onTrigger = function(player, npc)\n                    local party = player:getParty()\n\n                    if #party > 1 then\n                        return quest:progressEvent(129, { [1] = 2 })\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [129] = function(player, csid, option, npc)\n                    local partySizeRequirement = 2\n                    local party = player:getParty()\n                    local partySameRaceCount = 0\n\n                    if #party >= partySizeRequirement then\n                        for key, member in pairs(party) do\n                            if\n                                member:getZoneID() ~= player:getZoneID() or\n                                member:checkDistance(player) > 15\n                            then\n                                player:updateEvent(1)\n                                return\n                            else\n                                local pRace = player:getRace()\n                                local mRace = member:getRace()\n\n                                if\n                                    (pRace == xi.race.HUME_M or pRace == xi.race.HUME_F) and\n                                    (mRace == xi.race.HUME_M or mRace == xi.race.HUME_F)\n                                then\n                                    partySameRaceCount = partySameRaceCount + 1\n                                elseif\n                                    (pRace == xi.race.ELVAAN_M or pRace == xi.race.ELVAAN_F) and\n                                    (mRace == xi.race.ELVAAN_M or mRace == xi.race.ELVAAN_F)\n                                then\n                                    partySameRaceCount = partySameRaceCount + 1\n                                elseif\n                                    (pRace == xi.race.TARU_M or pRace == xi.race.TARU_F) and\n                                    (mRace == xi.race.TARU_M or mRace == xi.race.TARU_F)\n                                then\n                                    partySameRaceCount = partySameRaceCount + 1\n                                elseif pRace == xi.race.GALKA and mRace == xi.race.GALKA then\n                                    partySameRaceCount = partySameRaceCount + 1\n                                elseif pRace == xi.race.MITHRA and mRace == xi.race.MITHRA then\n                                    partySameRaceCount = partySameRaceCount + 1\n                                end\n                            end\n                        end\n                    else\n                        player:updateEvent(1)\n                        return\n                    end\n\n                    if partySameRaceCount >= partySizeRequirement then\n                        quest:setLocalVar(player, 'Prog', 1)\n                        player:updateEvent(15, 2)\n                        return\n                    else\n                        player:updateEvent(4, 2)\n                        return\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [129] = function(player, csid, option, npc)\n                    if option == 0 and quest:getLocalVar(player, 'Prog') == 1 then\n                        if quest:complete(player) then\n                            quest:setLocalVar(player, 'Prog', 0)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Introduction_to_Teamwork.lua"]={["Path"]="scripts/quests/sandoria/Introduction_to_Teamwork.lua",["SHA256"]="7ea743391c0661443c9fc7e7ab34d85509cca5601ae5d050b8f11687bd8393ad",["Text"]="-----------------------------------\n-- Introduction to Teamwork\n-----------------------------------\n-- Log ID: 0, Quest ID: 63\n-----------------------------------\n-- Vilatroire : !pos -260 -70 423 100\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.INTRODUCTION_TO_TEAMWORK)\n\nquest.reward =\n{\n    item     = xi.item.SHELL_RING,\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    title    = xi.title.THIRD_RATE_ORGANIZER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getFameLevel(xi.fameArea.SANDORIA) >= 2 and\n                        player:getMainLvl() >= 10\n                    then\n                        return quest:progressEvent(135)\n                    else\n                        return quest:event(134):replaceDefault()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [135] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] =\n            {\n                onTrigger = function(player, npc)\n                    local party = player:getParty()\n\n                    if #party > 1 then\n                        return quest:progressEvent(129, { [1] = 1 })\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [129] = function(player, csid, option, npc)\n                    local partySizeRequirement = 2\n                    local party = player:getParty()\n                    local partySameNationCount = 0\n\n                    if #party >= partySizeRequirement then\n                        for key, member in pairs(party) do\n                            if\n                                member:getZoneID() ~= player:getZoneID() or\n                                member:checkDistance(player) > 15\n                            then\n                                player:updateEvent(1)\n                                return\n                            else\n                                if member:getNation() == player:getNation() then\n                                    partySameNationCount = partySameNationCount + 1\n                                end\n                            end\n                        end\n                    else\n                        player:updateEvent(1)\n                        return\n                    end\n\n                    if partySameNationCount >= partySizeRequirement then\n                        quest:setLocalVar(player, 'Prog', 1)\n                        player:updateEvent(15, 1)\n                        return\n                    else\n                        player:updateEvent(3, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [129] = function(player, csid, option, npc)\n                    if option == 0 and quest:getLocalVar(player, 'Prog') == 1 then\n                        if quest:complete(player) then\n                            quest:setLocalVar(player, 'Prog', 0)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Lizard_Skins.lua"]={["Path"]="scripts/quests/sandoria/Lizard_Skins.lua",["SHA256"]="4dfbcb22cc00adb67e439eba3dacf7b77345aeeaf34d1080314afd57debf19bc",["Text"]="-----------------------------------\n-- Lizard Skins\n-----------------------------------\n-- Log ID: 0, Quest ID: 15\n-- Hanaa Punaa : !pos -179.726 -8.8 27.574 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.LIZARD_SKINS)\n\nquest.reward =\n{\n    fame = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    -- Repeatable Items handled within the Trigger:\n    -- item = xi.item.LIZARD_GLOVES,\n    -- title = xi.title.LIZARD_SKINNER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 2 and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_SEAMSTRESS)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(559)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(562)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [559] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [562] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] = quest:progressEvent(560),\n        },\n    },\n\n    -- These functions check the status of ~= xi.questStatus.QUEST_AVAILABLE to support repeating\n    -- the quest.  Does not have to be flagged again to complete an additional time.\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.LIZARD_SKIN, 3 } }) then\n                        return quest:progressEvent(561)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [561] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.LIZARD_GLOVES, { fromTrade = true }) then\n                        player:confirmTrade()\n                        player:addTitle(xi.title.LIZARD_SKINNER)\n                        if not player:hasCompletedQuest(quest.areaId, quest.questId) then\n                            quest:complete(player)\n                        else\n                            player:addFame(xi.fameArea.SANDORIA, 10)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and player:getFameLevel(xi.fameArea.SANDORIA) < 3\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] = quest:event(591):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Lufets_Lake_Salt.lua"]={["Path"]="scripts/quests/sandoria/Lufets_Lake_Salt.lua",["SHA256"]="0569ea780f93dc934b2b8f4cb53b48a270ea81917ca9c2a5132fe9d49069b724",["Text"]="-----------------------------------\n-- Lufets Lake Salt\n-----------------------------------\n-- Log ID: 0, Quest ID: 81\n-----------------------------------\n-- Nogelle : !pos -70 -5.5 -33 232\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.LUFETS_LAKE_SALT)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 600,\n    title    = xi.title.BEAN_CUISINE_SALTER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Nogelle'] = quest:progressEvent(12),\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Nogelle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.CHUNK_OF_LUFET_SALT, 3 } }) then\n                        return quest:progressEvent(11)\n                    end\n                end,\n\n                onTrigger = quest:event(10),\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Nogelle'] = quest:event(522):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Lure_of_the_Wildcat_Sandoria.lua"]={["Path"]="scripts/quests/sandoria/Lure_of_the_Wildcat_Sandoria.lua",["SHA256"]="8cd3d0c789766617d0df94f0d0b0cb2f319abdf492f368908960434b4474b372",["Text"]="-----------------------------------\n-- Lure of the Wildcat (San d'Oria)\n-----------------------------------\n-- !addquest 0 113\n-- Amutiyaal : !pos 116 0.1 84 230\n-----------------------------------\nlocal southernSanDoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.LURE_OF_THE_WILDCAT)\n\nquest.reward =\n{\n    fame     = 0,\n    fameArea = xi.fameArea.SANDORIA,\n    keyItem  = xi.keyItem.RED_INVITATION_CARD,\n}\n\nlocal wildcatNpcData =\n{\n    ['Daggao'       ] = {  0, 810 }, -- !pos 89 0 119 230\n    ['Authere'      ] = {  1, 809 }, -- !pos 33 1 -31 230\n    ['Rouva'        ] = {  2, 808 }, -- !pos -17 2 10 230\n    ['Femitte'      ] = {  3, 807 }, -- !pos -17 2 10 230\n    ['Deraquien'    ] = {  4, 811 }, -- !pos -98 -2 31 230\n    ['Giaunne'      ] = {  5, 805 }, -- !pos -13 0 36 231\n    ['Anilla'       ] = {  6, 808 }, -- !pos 8 0.1 61 231\n    ['Maloquedil'   ] = {  7, 807 }, -- !pos 35 0.1 60 231\n    ['Phairupegiont'] = {  8, 806 }, -- !pos -46 0.1 76 231\n    ['Bertenont'    ] = {  9, 809 }, -- !pos -165 0.1 226 231\n    ['Perdiouvilet' ] = { 10, 750 }, -- !pos -59 -5 -29 232\n    ['Pomilla'      ] = { 11, 749 }, -- !pos -38 -4 -55 232\n    ['Cherlodeau'   ] = { 12, 748 }, -- !pos -20 -4 -69 232\n    ['Parcarin'     ] = { 13, 747 }, -- !pos -9 -13 -151 232\n    ['Rugiette'     ] = { 14, 746 }, -- !pos 71 -9 -73 232\n    ['Curilla'      ] = { 15, 562 }, -- !pos 27 0.1 0.1 233\n    ['Halver'       ] = { 16, 558 }, -- !pos 2 0.1 0.1 233\n    ['Rahal'        ] = { 17, 559 }, -- !pos -28 0.1 -6 233\n    ['Perfaumand'   ] = { 18, 560 }, -- !pos -39 -3 69 233\n    ['Chalvatot'    ] = { 19, 561 }, -- !pos -105 0.1 72 233\n}\n\nlocal wildcatOnTrigger = function(player, npc)\n    local npcData = wildcatNpcData[npc:getName()]\n\n    if not quest:isVarBitsSet(player, 'Prog', npcData[1]) then\n        return quest:progressEvent(npcData[2])\n    end\nend\n\nlocal wildcatOnEventFinish = function(player, csid, option, npc)\n    quest:setVarBit(player, 'Prog', wildcatNpcData[npc:getName()][1])\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.settings.main.ENABLE_TOAU == 1\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Amutiyaal'] = quest:progressEvent(812),\n\n            onEventFinish =\n            {\n                [812] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.RED_SENTINEL_BADGE)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Chalvatot' ] = wildcatOnTrigger,\n            ['Curilla'   ] = wildcatOnTrigger,\n            ['Halver'    ] = wildcatOnTrigger,\n            ['Perfaumand'] = wildcatOnTrigger,\n            ['Rahal'     ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [558] = wildcatOnEventFinish,\n                [559] = wildcatOnEventFinish,\n                [560] = wildcatOnEventFinish,\n                [561] = wildcatOnEventFinish,\n                [562] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Anilla'       ] = wildcatOnTrigger,\n            ['Bertenont'    ] = wildcatOnTrigger,\n            ['Giaunne'      ] = wildcatOnTrigger,\n            ['Maloquedil'   ] = wildcatOnTrigger,\n            ['Phairupegiont'] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [805] = wildcatOnEventFinish,\n                [806] = wildcatOnEventFinish,\n                [807] = wildcatOnEventFinish,\n                [808] = wildcatOnEventFinish,\n                [809] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Cherlodeau'  ] = wildcatOnTrigger,\n            ['Parcarin'    ] = wildcatOnTrigger,\n            ['Perdiouvilet'] = wildcatOnTrigger,\n            ['Pomilla'     ] = wildcatOnTrigger,\n            ['Rugiette'    ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [746] = wildcatOnEventFinish,\n                [747] = wildcatOnEventFinish,\n                [748] = wildcatOnEventFinish,\n                [749] = wildcatOnEventFinish,\n                [750] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Amutiyaal'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(813)\n                    elseif utils.mask.isFull(questProgress, 20) then\n                        return quest:progressEvent(815)\n                    else\n                        return quest:event(814)\n                    end\n                end,\n            },\n\n            ['Authere'  ] = wildcatOnTrigger,\n            ['Daggao'   ] = wildcatOnTrigger,\n            ['Deraquien'] = wildcatOnTrigger,\n            ['Femitte'  ] = wildcatOnTrigger,\n            ['Rouva'    ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [807] = wildcatOnEventFinish,\n                [808] = wildcatOnEventFinish,\n                [809] = wildcatOnEventFinish,\n                [810] = wildcatOnEventFinish,\n                [811] = wildcatOnEventFinish,\n\n                [815] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.RED_SENTINEL_BADGE)\n                    player:messageSpecial(southernSanDoriaID.text.KEYITEM_LOST, xi.keyItem.RED_SENTINEL_BADGE)\n\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Messenger_From_Beyond.lua"]={["Path"]="scripts/quests/sandoria/Messenger_From_Beyond.lua",["SHA256"]="c20015239d47d7e4864db9886ee985f81f24b241e071e3bba236e90151350756",["Text"]="-----------------------------------\n-- Messenger From Beyond\n-----------------------------------\n-- Log ID: 0, Quest ID: 87\n-----------------------------------\n-- Narcheral : !pos 129 -11 126 231\n-- qm2       : !pos -716 -10 66 103\n-----------------------------------\nlocal ID = zones[xi.zone.VALKURM_DUNES]\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.MESSENGER_FROM_BEYOND)\n\nquest.reward =\n{\n    item     = xi.item.BLESSED_HAMMER,\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL and\n                player:getMainJob() == xi.job.WHM\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Narcheral'] = quest:progressEvent(689),\n\n            onEventFinish =\n            {\n                [689] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.VALKURM_DUNES] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasItem(xi.item.TAVNAZIA_PASS) and\n                        npcUtil.popFromQM(player, npc, ID.mob.MARCHELUTE, { hide = 0 })\n                    then\n                        return quest:messageSpecial(ID.text.FOUL_PRESENCE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Narcheral'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.TAVNAZIA_PASS) then\n                        return quest:progressEvent(690)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [690] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Methods_Create_Madness.lua"]={["Path"]="scripts/quests/sandoria/Methods_Create_Madness.lua",["SHA256"]="ba06f27e9492bff472a2654740e7f5712d95b25a3fedad2dd29973c95703c07e",["Text"]="-----------------------------------\n-- Methods Create Madness\n-- Balasiel !pos -136 -11 64 230\n-- qm1 !pos 107 0.7 -125.25 176\n-----------------------------------\nlocal southernSandOriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\nlocal seaSerpentGrottoID = zones[xi.zone.SEA_SERPENT_GROTTO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.METHODS_CREATE_MADNESS)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    -- Talk to Balasiel in Southern San d'Oria who will give you the Spear of Trials and the Weapon Training Guide.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.SPEAR_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.POLEARM) / 10 >= 240 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(8):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        (player:hasItem(xi.item.SPEAR_OF_TRIALS) or npcUtil.giveItem(player, xi.item.SPEAR_OF_TRIALS))\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Perform Weapon Skills with the Spear of Trials on monsters that grant XP until the latent effect disappears.\n    -- Once you no longer receive the latent effect bonus, trade the Spear of Trials back to Balasiel, who will\n    -- take the weapon from you and give you a Map to the Annals of Truth and tell you to head to Sea Serpent Grotto.\n    -- Click the ??? to spawn the NM Water Leaper.\n    -- Once the NM is dead, reexamine the ??? to obtain the Annals of Truth.\n    -- Bring this back to Balasiel for your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(13) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(12) -- cont 2\n                    else\n                        return quest:event(11, player:hasItem(xi.item.SPEAR_OF_TRIALS) and 1 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SPEAR_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(10) -- unfinished weapon\n                        else\n                            return quest:progressEvent(9) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.SPEAR_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.SPEAR_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.METHODS_CREATE_MADNESS)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [9] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.IMPULSE_DRIVE)\n                        player:messageSpecial(southernSandOriaID.text.IMPULSE_DRIVE_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SEA_SERPENT_GROTTO] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, seaSerpentGrottoID.mob.WATER_LEAPER, { hide = 0 })\n                    then\n                        return quest:messageSpecial(seaSerpentGrottoID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Water_Leaper'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Old_Wounds.lua"]={["Path"]="scripts/quests/sandoria/Old_Wounds.lua",["SHA256"]="f31f89d6e309b5a65662c6c9e950f304ce10e5ad472260b52b3c22cb02709e20",["Text"]="-----------------------------------\n-- Old Wounds\n-- Curilla !pos 27 0.1 0.1 233\n-- qm3 !pos -145 2 446 208\n-----------------------------------\nlocal chateauID = zones[xi.zone.CHATEAU_DORAGUILLE]\nlocal quicksandCavesID = zones[xi.zone.QUICKSAND_CAVES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.OLD_WOUNDS)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.SAPARA_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.SWORD) / 10 >= 240 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(43):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [43] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        (\n                            player:hasItem(xi.item.SAPARA_OF_TRIALS) or\n                            npcUtil.giveItem(player, xi.item.SAPARA_OF_TRIALS)\n                        )\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(48) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(47) -- cont 2\n                    else\n                        return quest:event(46, player:hasItem(xi.item.SAPARA_OF_TRIALS) and 1 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SAPARA_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(45) -- unfinished weapon\n                        else\n                            return quest:progressEvent(44) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [46] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.SAPARA_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.SAPARA_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.OLD_WOUNDS)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [44] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [48] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.SAVAGE_BLADE)\n                        player:messageSpecial(chateauID.text.SAVAGE_BLADE_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.QUICKSAND_CAVES] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, quicksandCavesID.mob.GIRTABLULU, { hide = 0 })\n                    then\n                        return quest:messageSpecial(quicksandCavesID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Girtablulu'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Prelude_of_Black_and_White.lua"]={["Path"]="scripts/quests/sandoria/Prelude_of_Black_and_White.lua",["SHA256"]="3ca247829bd94a777e435ef28f8c58d74e85441072d9a8af860ad0b4179a85ef",["Text"]="-----------------------------------\n-- Prelude of Black and White\n-----------------------------------\n-- Log ID: 0, Quest ID: 88\n-----------------------------------\n-- _6h1      : !pos -37 -3 31 233\n-- Narcheral : !pos 129 -11 126 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.PRELUDE_OF_BLACK_AND_WHITE)\n\nquest.reward =\n{\n    item     = xi.item.HEALERS_DUCKBILLS,\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.MESSENGER_FROM_BEYOND) and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL and\n                player:getMainJob() == xi.job.WHM\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['_6h1'] = quest:progressEvent(551),\n\n            onEventFinish =\n            {\n                [551] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Narcheral'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.CANTEEN_OF_YAGUDO_HOLY_WATER, xi.item.MOCCASINS }) then\n                        return quest:progressEvent(691)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [691] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/RDM_AF1_The_Crimson_Trial.lua"]={["Path"]="scripts/quests/sandoria/RDM_AF1_The_Crimson_Trial.lua",["SHA256"]="2072590f1b4916b49510f02d2eed048b5bcb4ce236c66d90debfa6451aeabbba",["Text"]="-----------------------------------\n-- The Crimson Trial\n-- Variable Prefix: [0][84]\n-----------------------------------\n-- ZONE                NPC          POS\n-- Southern San'doria, Sharzalion,  !pos 95   0 111 230\n-- Southern San'doria, Valderotaux, !pos 97 0.1 113 230\n-----------------------------------\nlocal davoiID = zones[xi.zone.DAVOI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_CRIMSON_TRIAL)\n\nquest.reward =\n{\n    item     = xi.item.FENCING_DEGEN,\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.RDM and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sharzalion'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(70) -- First starting event.\n                    else\n                        return quest:progressEvent(71) -- Next starting event if originaly declined.\n                    end\n                end,\n            },\n\n            ['Valderotaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(54, player:getPlaytime())\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [54] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(54, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [70] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest.\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1) -- This variable only means you rejected the quest when first offered.\n                    end\n                end,\n\n                [71] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.DAVOI] =\n        {\n            ['Storage_Hole'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(davoiID.text.AN_ORCISH_STORAGE_HOLE)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.DAVOI_STORAGE_KEY) and\n                        not player:hasKeyItem(xi.keyItem.ORCISH_DRIED_FOOD)\n                    then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.ORCISH_DRIED_FOOD)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    not player:hasKeyItem(xi.keyItem.ORCISH_DRIED_FOOD) and\n                    not GetMobByID(davoiID.mob.PURPLEFLASH_BRUKDOK):isSpawned()\n                then\n                    SpawnMob(davoiID.mob.PURPLEFLASH_BRUKDOK) -- Spawned by Quest: The Crimson Trial upon entering the zone\n                end\n            end,\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sharzalion'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ORCISH_DRIED_FOOD) then\n                        return quest:progressEvent(75) -- Finish quest.\n                    else\n                        return quest:event(74) -- Reminder.\n                    end\n                end,\n            },\n\n            ['Valderotaux'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(54, player:getPlaytime())\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [54] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(54, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [75] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ORCISH_DRIED_FOOD)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/RDM_AF2_Enveloped_in_Darkness.lua"]={["Path"]="scripts/quests/sandoria/RDM_AF2_Enveloped_in_Darkness.lua",["SHA256"]="c355d27f124b64f0d13df1d0c490629c3f89c21db5bf988dffb6d21136397d1d",["Text"]="-----------------------------------\n-- Enveloped in Darkness (RDM AF2)\n-- Variable Prefix: [0][85]\n-----------------------------------\n-- ZONE                 NPC          POS\n-- Chateau d'Oraguille, Curilla,     !pos 27 0.1 0.1 233\n-- Northern San'doria,  Pagisalis,   !pos 97 0.1 113 231\n-----------------------------------\nlocal crawlersID = zones[xi.zone.CRAWLERS_NEST]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.ENVELOPED_IN_DARKNESS)\n\nquest.reward =\n{\n    item     = xi.item.WARLOCKS_BOOTS,\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_CRIMSON_TRIAL) == xi.questStatus.QUEST_COMPLETED and\n                player:getMainJob() == xi.job.RDM and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(94) -- First starting event.\n                    else\n                        return quest:progressEvent(95) -- Next starting event if originaly declined.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [94] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest.\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.OLD_POCKET_WATCH)\n                    else\n                        quest:setVar(player, 'Prog', 1) -- You rejected the quest when first offered.\n                    end\n                end,\n\n                [95] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest.\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.OLD_POCKET_WATCH)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sharzalion'] = quest:event(68)\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') <= 1 then\n                        return quest:event(92) -- Church reminder.\n                        -- NOTE: Curilla has a second posible reminder event in this step (event 93). From context, it seems time triggered.\n                    elseif quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(101) -- Post church ghost event. (Optional)\n                    else\n                        return quest:event(107) -- Crawler blood reminder.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3) -- Set optional event as seen.\n                end,\n            },\n        },\n\n        [xi.zone.CRAWLERS_NEST] =\n        {\n            ['qm8'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') >= 2 then\n                        if quest:getVar(player, 'Time') > 0 then\n                            if quest:getVar(player, 'Time') <= GetSystemTime() then\n                                return quest:progressEvent(5) -- Quest complete.\n                            else\n                                return quest:messageSpecial(crawlersID.text.EQUIPMENT_NOT_PURIFIED) -- Purification incomplete.\n                            end\n                        else\n                            if\n                                player:hasKeyItem(xi.keyItem.CRAWLER_BLOOD) and\n                                player:hasKeyItem(xi.keyItem.OLD_BOOTS)\n                            then\n                                return quest:progressEvent(4) -- Loose key items. Start boot purification.\n                            else\n                                return quest:messageSpecial(crawlersID.text.SOMEONE_HAS_BEEN_DIGGING_HERE)\n                            end\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    if option == 1 then\n                        -- Set purification time.\n                        quest:setVar(player, 'Time', GetSystemTime() + 30)\n\n                        -- Delete Key items.\n                        player:delKeyItem(xi.keyItem.CRAWLER_BLOOD)\n                        player:delKeyItem(xi.keyItem.OLD_BOOTS)\n\n                        -- Message when acepting to bury boots and blood.\n                        player:messageSpecial(crawlersID.text.YOU_BURY_THE, xi.keyItem.OLD_BOOTS, xi.keyItem.CRAWLER_BLOOD)\n                    end\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Pagisalis'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SQUARE_OF_VELVET_CLOTH) then\n                        return quest:progressEvent(37)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') >= 2 then\n                        return quest:event(58) -- After seing ghost.\n                    else\n                        return quest:event(48)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [37] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2) -- Saw ghost.\n                    player:tradeComplete()\n                    player:delKeyItem(xi.keyItem.OLD_POCKET_WATCH)\n                    npcUtil.giveKeyItem(player, xi.keyItem.OLD_BOOTS)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sharzalion'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') >= 2 then\n                        return quest:event(69) -- After seing ghost.\n                    else\n                        return quest:event(68)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Rosel_the_Armorer.lua"]={["Path"]="scripts/quests/sandoria/Rosel_the_Armorer.lua",["SHA256"]="d82520b579c65d6ab7a470f87e3171a0e1ed2330fe099df998023004b265a2fc",["Text"]="-----------------------------------\n-- Rosel the Armorer\n-----------------------------------\n-- Log ID: 0, Quest ID: 2\n-- Rosel    : !pos 69.895 0 41.073 230\n-- Guilerme : !pos -4.5 0 99 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.ROSEL_THE_ARMORER)\n\nquest.reward =\n{\n    -- Delivered to correct Prince: 200G, Incorrect Prince: 100G\n    title = xi.title.ENTRANCE_DENIED,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Rosel'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local questStage = quest:getVar(player, 'Stage')\n\n                    -- On triggering this CS, set a value to determine if Pieuje or Trion is the intended\n                    -- recipient.  This will persist until the quest is completed, and is one higher than\n                    -- the parameter value (1 == Pieuje, 2 == Trion)\n\n                    -- Using questStage directly eliminates the need for an additional questProgress state\n                    -- and the subsequent need for an additional db write on that change.\n                    if questStage == 0 then\n                        questStage = math.randomInt(1, 2)\n                        quest:setVar(player, 'Stage', questStage)\n                    end\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(523, 0, 0, 0, 0, questStage - 1)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(524, 0, 0, 0, 0, questStage - 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [523] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.RECEIPT_FOR_THE_PRINCE)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [524] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.RECEIPT_FOR_THE_PRINCE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Rosel'] =\n            {\n                onTrigger = function(player, npc)\n                    local questStage = quest:getVar(player, 'Stage')\n                    if player:hasKeyItem(xi.keyItem.RECEIPT_FOR_THE_PRINCE) then\n                        return quest:progressEvent(524, 0, 0, 0, 0, questStage - 1)\n                    else\n                        local questOption = quest:getVar(player, 'Option')\n                        return quest:progressEvent(527, 0, 0, 0, 0, questStage - 1, questOption)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [527] = function(player, csid, option, npc)\n                    local gilReward = 100\n                    local fameReward = 10\n\n                    if option == 0 then\n                        gilReward = 200\n                        fameReward = 20\n                    end\n\n                    npcUtil.giveCurrency(player, 'gil', gilReward)\n                    player:addFame(xi.fameArea.SANDORIA, fameReward)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Guilerme'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.RECEIPT_FOR_THE_PRINCE) then\n                        local questStage = quest:getVar(player, 'Stage')\n                        return quest:progressEvent(507, 0, 0, 0, 0, 0, 0, questStage - 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [507] = function(player, csid, option, npc)\n                    -- The option returned from this event determines whether the player\n                    -- has chosen correctly or not.  Option 0 is correct answer, while\n                    -- option 1 was an incorrect answer.\n                    quest:setVar(player, 'Option', option)\n                    player:delKeyItem(xi.keyItem.RECEIPT_FOR_THE_PRINCE)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Sharpening_the_Sword.lua"]={["Path"]="scripts/quests/sandoria/Sharpening_the_Sword.lua",["SHA256"]="8ead108bd86636d1abf5f84a8c36cc80c7ab24a18e89736f2f12d62964bcc0d3",["Text"]="-----------------------------------\n-- Sharpening the Sword\n-----------------------------------\n-- Log ID: 0, Quest ID: 90\n-----------------------------------\n-- Ailbeche   : !pos 4 -1 24 231\n-- Sobane     : !pos -190 -3 97 230\n-- Stalagmite : !pos -51 0.1 3 193\n-----------------------------------\nlocal northID = zones[xi.zone.NORTHERN_SAN_DORIA]\nlocal cavesID = zones[xi.zone.ORDELLES_CAVES]\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.SHARPENING_THE_SWORD)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.HONOR_SWORD,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasTitle(xi.title.FAMILY_COUNSELOR) and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL and\n                player:getMainJob() == xi.job.PLD\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(45)\n                    else\n                        return quest:event(43):setPriority(200)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [43] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Option', 0)\n                        quest:begin(player)\n                    end\n                end,\n\n                [45] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                not player:hasKeyItem(xi.keyItem.ORDELLE_WHETSTONE)\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] = quest:event(42),\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] = quest:event(52),\n        },\n\n        [xi.zone.ORDELLES_CAVES] =\n        {\n            ['Stalagmite'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasKilled = quest:getLocalVar(player, 'Stage')\n                    if hasKilled == 1 then\n                        quest:setLocalVar(player, 'Stage', 0)\n                        return quest:keyItem(xi.keyItem.ORDELLE_WHETSTONE)\n                    elseif npcUtil.popFromQM(player, npc, cavesID.mob.POLEVIK, { hide = 0 }) then\n                        return quest:noAction()\n                    else\n                        player:messageSpecial(cavesID.text.DRY_WIND + 1, xi.keyItem.ORDELLE_WHETSTONE)\n                        return quest:messageSpecial(cavesID.text.DRY_WIND)\n                    end\n                end,\n            },\n\n            ['Polevik'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setLocalVar(player, 'Stage', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.ORDELLE_WHETSTONE)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] = quest:event(52),\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] = quest:progressEvent(44),\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ORDELLE_WHETSTONE)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOY_S_DREAM) == xi.quest.status.AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] = quest:message(northID.text.AILBECHE_WHEN_FISHING):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Signed_in_Blood.lua"]={["Path"]="scripts/quests/sandoria/Signed_in_Blood.lua",["SHA256"]="3d0c2212bcaf730f27013870c1162daf3dcfbef87e7ebc2bdde692ba80c634e1",["Text"]="-----------------------------------\n-- Signed in  Blood\n-- Sobane !pos -190 -3 97 230\n-- CATHEDRAL_TAPESTRY !additem 1662\n-- Abelard !pos -52 -11 -13 248\n-- TORN_OUT_PAGES !addkeyitem 626\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.SIGNED_IN_BLOOD)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.CUNNING_EARRING,\n    gil      = 3500,\n}\n\nquest.sections =\n{\n    -- Talk to Sobane, she is willing to give you a quest, but she needs to be able to trust that you'll keep your mouth shut.\n    -- She wants you to retrieve a Cathedral Tapestry.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.SANDORIA) >= 3\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(732, 0, xi.item.CATHEDRAL_TAPESTRY)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [732] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Trade the tapestry to Sobane and she'll explain the next step.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(733, 0, xi.item.CATHEDRAL_TAPESTRY)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.CATHEDRAL_TAPESTRY) then\n                        return quest:progressEvent(734, 0, xi.item.CATHEDRAL_TAPESTRY)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [734] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n\n    -- Travel to Selbina. Talk to Abelard, and he'll mention a diary he found, with missing pages.\n    -- Perhaps his lips will loosen if you help him find them.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(735)\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(1104)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1104] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Travel to Ordelle's Caves and hunt for an Ordelle Chest Key. Once you find a key, look for a Treasure Chest and open it.\n    -- Return to Selbina and talk to the mayor. He'll reveal some information to you which will prove interesting to Sobane.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.ORDELLES_CAVES] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.TORN_OUT_PAGES) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.TORN_OUT_PAGES)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TORN_OUT_PAGES) then\n                        return quest:progressEvent(1106)\n                    else\n                        return quest:event(1105)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1106] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(735)\n                end,\n            },\n        },\n    },\n\n    -- Return to Sobane to complete this quest and to receive your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(48)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(736)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [736] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.TORN_OUT_PAGES)\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- If you just completed Signed in Blood, you must zone out and back into Southern San d'Oria to flag Tea with a Tonberry\n    -- Otherwise you get this event.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and player:needToZone()\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(737)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Sleepless_Nights.lua"]={["Path"]="scripts/quests/sandoria/Sleepless_Nights.lua",["SHA256"]="628e7ee3dc4b5ab6d2d9f52c5a9c47d888aa862ff74feb9437ca4cb02c568ef9",["Text"]="-----------------------------------\n-- Sleepless Nights\n-----------------------------------\n-- Log ID: 0, Quest ID: 80\n-----------------------------------\n-- Paouala : !pos 158 -6 17 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.SLEEPLESS_NIGHTS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 5000,\n    title    = xi.title.SHEEPS_MILK_DELIVERER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 2\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Paouala'] = quest:progressEvent(85),\n\n            onEventFinish =\n            {\n                [85] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Paouala'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.JUG_OF_MARYS_MILK) then\n                        return quest:progressEvent(84)\n                    end\n                end,\n\n                onTrigger = quest:event(83),\n            },\n\n            onEventFinish =\n            {\n                [84] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Paouala'] = quest:event(81):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Souls_in_Shadow.lua"]={["Path"]="scripts/quests/sandoria/Souls_in_Shadow.lua",["SHA256"]="5c0f522f1583d8cf1d737362691fbeaf5a4c9e38b78eae3f7b2ef2849f16711a",["Text"]="-----------------------------------\n-- Souls in Shadow\n-- Novalmauge !pos 70 -24 21 167\n-- qm2 !pos 118 36 -281 160\n-----------------------------------\nlocal bostaunieuxID = zones[xi.zone.BOSTAUNIEUX_OUBLIETTE]\nlocal denOfRancorID = zones[xi.zone.DEN_OF_RANCOR]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.SOULS_IN_SHADOW)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.SCYTHE_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.SCYTHE) / 10 >= 240 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(0):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        (\n                            player:hasItem(xi.item.SCYTHE_OF_TRIALS) or\n                            npcUtil.giveItem(player, xi.item.SCYTHE_OF_TRIALS)\n                        )\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(5) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(4) -- cont 2\n                    else\n                        return quest:event(3, player:hasItem(xi.item.SCYTHE_OF_TRIALS) and 1 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SCYTHE_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(2) -- unfinished weapon\n                        else\n                            return quest:progressEvent(1) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.SCYTHE_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.SCYTHE_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.SOULS_IN_SHADOW)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [1] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.SPIRAL_HELL)\n                        player:messageSpecial(bostaunieuxID.text.SPIRAL_HELL_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.DEN_OF_RANCOR] =\n        {\n            ['qm_mokumokuren'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, denOfRancorID.mob.MOKUMOKUREN, { hide = 0 })\n                    then\n                        return quest:messageSpecial(denOfRancorID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Mokumokuren'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Spice_Gals.lua"]={["Path"]="scripts/quests/sandoria/Spice_Gals.lua",["SHA256"]="719699479d051be4891ae44e67a724281e1d977bb8792b602f044acf2d3064e4",["Text"]="-----------------------------------\n-- Spice Gals\n-----------------------------------\n-- Log ID: 0, Quest ID: 110\n-----------------------------------\n-- CoP 3-1             : !addmission 6 258\n-- Rouva               : !pos -16.194 2.101 11.805\n-- Riverne - Site #A01 : !pos -514.717 -6.684 -407.314\n-- Riverne - Site #B01 : !pos -517.137 0.094 689.199\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.SPICE_GALS)\n\nquest.reward =\n{\n    item = xi.item.MIRATETES_MEMOIRS,\n    fame = 0,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return vars.Prog == 0 and\n            vars.Wait < NextConquestTally() and\n            player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.ANCIENT_VOWS)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Rouva'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SPICE_GALS) == xi.questStatus.QUEST_AVAILABLE then\n                        return quest:progressEvent(724)\n                    else\n                        return quest:progressEvent(726) -- Repeat after conquest tally\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [724] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [726] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Prog == 1\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Rouva'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SPICE_GALS) == xi.questStatus.QUEST_ACCEPTED and\n                        player:hasKeyItem(xi.keyItem.RIVERNEWORT)\n                    then\n                        return quest:progressEvent(725) -- First time completion\n                    elseif\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SPICE_GALS) == xi.questStatus.QUEST_COMPLETED and\n                        player:hasKeyItem(xi.keyItem.RIVERNEWORT)\n                    then\n                        return quest:progressEvent(727) -- Repeat completion\n                    else\n                        return quest:event(728):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [725] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.RIVERNEWORT)\n                        quest:setVar(player, 'Wait', NextConquestTally())\n                    end\n                end,\n\n                [727] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.RIVERNEWORT)\n                        quest:setVar(player, 'Wait', NextConquestTally())\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.RIVERNE_SITE_A01] =\n        {\n            ['qm_rivernewort'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.RIVERNEWORT) then\n                        return quest:keyItem(xi.keyItem.RIVERNEWORT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.RIVERNE_SITE_B01] =\n        {\n            ['qm_rivernewort'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.RIVERNEWORT) then\n                        return quest:keyItem(xi.keyItem.RIVERNEWORT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Starting_a_Flame.lua"]={["Path"]="scripts/quests/sandoria/Starting_a_Flame.lua",["SHA256"]="4405ee1fd8644bfabd90fb126be7414495e5511a1d5920f1f8254d97032522b8",["Text"]="-----------------------------------\n-- Starting a Flame\n-----------------------------------\n-- Log ID: 0, Quest ID: 77\n-----------------------------------\n-- Legata : !pos 82 0 116 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.STARTING_A_FLAME)\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Legata'] = quest:progressEvent(37),\n\n            onEventFinish =\n            {\n                [37] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Legata'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.FLINT_STONE, 4 } }) then\n                        return quest:progressEvent(36)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.STARTING_A_FLAME) == xi.questStatus.QUEST_ACCEPTED then\n                        return quest:event(35)\n                    else\n                        return quest:event(37, { [7] = 1 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [36] = function(player, csid, option, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.STARTING_A_FLAME) == xi.questStatus.QUEST_ACCEPTED then\n                        quest:complete(player)\n                    end\n\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                    npcUtil.giveCurrency(player, 'gil', 100)\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Tea_with_a_Tonberry.lua"]={["Path"]="scripts/quests/sandoria/Tea_with_a_Tonberry.lua",["SHA256"]="78c26439b8633392383bb3b20bc54ee3519dccb9d0804673874be503d5a4ccc3",["Text"]="-----------------------------------\n-- Tea with a Tonberry?\n-- Sobane !pos -190 -3 97 230\n-- Anguenet !pos 214.672 -3.013 -527.561 2\n-- PIECE_OF_ATTOHWA_GINSENG !additem 1683\n-- Riche !pos 5.945 -3.75 13.612 1\n-- INGOT_OF_ROYAL_TREASURY_GOLD !additem 1682\n-- Davoi qm2 !pos 189.201 1.2553 -383.921 149\n-----------------------------------\nlocal phanauetID = zones[xi.zone.PHANAUET_CHANNEL]\nlocal davoiID = zones[xi.zone.DAVOI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.TEA_WITH_A_TONBERRY)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.WILLPOWER_TORQUE,\n    title    = xi.title.TALKS_WITH_TONBERRIES,\n}\n\nquest.sections =\n{\n    -- Talk to Sobane. She and her husband need your help confirming a threat to a local aristocrat, but the only ones\n    -- who may know about it are the tight lipped Tonberries in Carpenters' Landing.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SIGNED_IN_BLOOD) == xi.questStatus.QUEST_COMPLETED and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 4 and\n                not player:needToZone()\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(738)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [738] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Travel to Attohwa Chasm and defeat Gallinipper, Ogrefly, or Monarch Ogrefly until they drop Attohwa Ginseng.\n    -- Travel to South Landing in Carpenters' Landing. Talk with Anguenet at the docks for a cutscene.\n    -- Trade Anguenet the Attohwa Ginseng and he will give you the Tonberry Blackboard.\n    -- Board a barge headed for Central Landing via Emfea Way.\n    -- Talk to Riche, the Tonberry on board. Ask him all the questions (5); at the end he'll take the key item.\n    -- Be sure to do this before the ride is over, which is approximately 7 minutes.\n    -- Travel to Fei'Yin and kill Shadow until they drop Treasury Gold.\n    -- Take the Treasury Gold to Davoi and trade it to the ??? at (J-11), which spawns a Hematic Cyst NM.\n    -- Kill the Hematic Cyst and select the ??? again for a cutscene.\n    -- Return to Southern San d'Oria and talk to Sobane to complete the quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Sobane'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(740)\n                    else\n                        return quest:event(739)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [740] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.CARPENTERS_LANDING] =\n        {\n            ['Anguenet'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(27, 0, xi.item.PIECE_OF_ATTOHWA_GINSENG)\n                    elseif progress == 1 then\n                        return quest:replaceEvent(28, 0, xi.item.PIECE_OF_ATTOHWA_GINSENG)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHas(trade, xi.item.PIECE_OF_ATTOHWA_GINSENG)\n                    then\n                        return quest:progressEvent(29)\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [27] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [29] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.TONBERRY_BLACKBOARD)\n                    quest:setVar(player, 'Prog', 2)\n                    player:confirmTrade()\n                end,\n            },\n        },\n\n        [xi.zone.PHANAUET_CHANNEL] =\n        {\n            ['Riche'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TONBERRY_BLACKBOARD) then\n                        return quest:progressEvent(5, 1, 627, xi.item.INGOT_OF_ROYAL_TREASURY_GOLD, 63, 3, 30, 30, 0)\n                    elseif quest:getVar(player, 'Prog') == 3 then\n                        return quest:messageName(phanauetID.text.RICHE_DAVOI_WATERFALL, 0, 0, xi.item.INGOT_OF_ROYAL_TREASURY_GOLD):replaceDefault()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    player:delKeyItem(xi.keyItem.TONBERRY_BLACKBOARD) -- No message as the cutscene ends with the NPC taking it\n                end,\n            },\n        },\n\n        [xi.zone.DAVOI] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 3 then\n                        return quest:messageSpecial(davoiID.text.WHERE_THE_TONBERRY_TOLD_YOU, 0, xi.item.INGOT_OF_ROYAL_TREASURY_GOLD)\n                    elseif progress == 4 then\n                        return quest:event(126, 149, xi.item.INGOT_OF_ROYAL_TREASURY_GOLD)\n                    elseif progress == 5 then\n                        return quest:messageSpecial(davoiID.text.NOTHING_TO_DO)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        npcUtil.tradeHas(trade, xi.item.INGOT_OF_ROYAL_TREASURY_GOLD) and\n                        npcUtil.popFromQM(player, npc, davoiID.mob.HEMATIC_CYST, { radius = 1, hide = 0 })\n                    then\n                        player:confirmTrade()\n                        return quest:messageSpecial(davoiID.text.UNDER_ATTACK)\n                    end\n                end,\n            },\n\n            ['Hematic_Cyst'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [126] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Brugaire_Consortium.lua"]={["Path"]="scripts/quests/sandoria/The_Brugaire_Consortium.lua",["SHA256"]="94e243a321d774e7ae9a711c4a4a351fe1884f32063685bd58f15e1c4f4bc69c",["Text"]="-----------------------------------\n-- The Brugaire Consortium\n-----------------------------------\n-- Log ID: 0, Quest ID: 12\n-- Fontoumant : !pos -10 -10 -122 232\n-- Regine     : !pos 68 -9 -74 232\n-- Apstaule   : !pos -6.983 -13.3 -157.517\n-- Thierride  : !pos -67 -5 -28 232\n-----------------------------------\n\n---@type TQuest\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_BRUGAIRE_CONSORTIUM)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.LAUAN_SHIELD,\n    title    = xi.title.COURIER_EXTRAORDINAIRE,\n}\n\n-- NOTE: Event Ids in Index 1 are for the next event (Option), while item is\n-- used by quest progress (Prog)\nlocal parcelItemIds =\n{\n    [0] = { 511, xi.item.PARCEL_FOR_THE_MAGIC_SHOP    },\n    [1] = { 512, xi.item.PARCEL_FOR_THE_AUCTION_HOUSE },\n    [2] = { 515, xi.item.PARCEL_FOR_THE_PUB           },\n}\n\nlocal tradeOnEventFinish = function(player, csid, option, npc)\n    player:confirmTrade()\n    quest:incrementVar(player, 'Prog', 1)\nend\n\nlocal triggerOnEventFinish = function(player, csid, option, npc)\n    if npcUtil.giveItem(player, parcelItemIds[quest:getVar(player, 'Prog')][2]) then\n        quest:incrementVar(player, 'Option', 1)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Fontoumant'] = quest:progressEvent(509),\n\n            onEventFinish =\n            {\n                [509] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        npcUtil.giveItem(player, xi.item.PARCEL_FOR_THE_MAGIC_SHOP)\n                    then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Fontoumant'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress < 3 and\n                        questProgress == quest:getVar(player, 'Option') and\n                        npcUtil.tradeHasExactly(trade, { { 'gil', 100 } })\n                    then\n                        return quest:progressEvent(608 + questProgress)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local questOption   = quest:getVar(player, 'Option')\n\n                    if questProgress > questOption then\n                        return quest:progressEvent(parcelItemIds[questOption][1])\n                    else\n                        return quest:event(560)\n                    end\n                end,\n            },\n\n            ['Regine'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeHasExactly(trade, xi.item.PARCEL_FOR_THE_MAGIC_SHOP)\n                    then\n                        return quest:progressEvent(535)\n                    end\n                end,\n            },\n\n            ['Apstaule'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHasExactly(trade, xi.item.PARCEL_FOR_THE_AUCTION_HOUSE)\n                    then\n                        return quest:progressEvent(540)\n                    end\n                end,\n            },\n\n            ['Thierride'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHasExactly(trade, xi.item.PARCEL_FOR_THE_PUB)\n                    then\n                        return quest:progressEvent(539)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [511] = triggerOnEventFinish,\n                [512] = triggerOnEventFinish,\n\n                [515] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [535] = tradeOnEventFinish,\n                [539] = tradeOnEventFinish,\n                [540] = tradeOnEventFinish,\n                [608] = tradeOnEventFinish,\n                [609] = tradeOnEventFinish,\n                [610] = tradeOnEventFinish,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Competition.lua"]={["Path"]="scripts/quests/sandoria/The_Competition.lua",["SHA256"]="11405a49455a69410ae71bcba3e3f21c98daf842da50d43e7e128b5d9b9e3f78",["Text"]="-----------------------------------\n-- The Competition\n-- Log ID: 0, Quest ID: 76\n-- Joulet !pos -18 -2 -45 232\n-----------------------------------\nlocal portSandOriaID = zones[xi.zone.PORT_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_COMPETITION)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.LU_SHANGS_FISHING_ROD,\n    keyItem  = xi.keyItem.TESTIMONIAL,\n    title    = xi.title.CARP_DIEM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_RIVALRY) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Ufanne'] = quest:event(310),\n\n            ['Joulet'] = quest:progressEvent(304, xi.item.MOAT_CARP_1, xi.item.FOREST_CARP),\n\n            onEventFinish =\n            {\n                [304] = function(player, csid, option, npc)\n                    if option == 700 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Joulet'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageName(portSandOriaID.text.JOULET_CARP_STATUS, 0, player:getCharVar('carpsTraded'), 0, 0, true, false) -- TODO: The number that Joulet reports increases over time and eventually resets back to 0 before starting to tick back up.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local count        = trade:getItemCount()\n                    local moatCarp     = trade:getItemQty(xi.item.MOAT_CARP_1)\n                    local forestCarp   = trade:getItemQty(xi.item.FOREST_CARP)\n                    local fishCountVar = player:getCharVar('carpsTraded')\n                    local totalFish    = moatCarp + forestCarp + fishCountVar\n\n                    if moatCarp + forestCarp > 0 and moatCarp + forestCarp == count then\n                        if totalFish >= 10000 then\n                            player:setLocalVar('FishTraded', totalFish) -- Used to transfer the variable into oneventfinish\n                            player:setLocalVar('GilToReward', moatCarp * 10 + forestCarp * 15) -- Forces the gil reward to happen AFTER the event like in captures\n                            return quest:progressEvent(307)\n                        else\n                            player:setLocalVar('FishTraded', totalFish) -- Used to transfer the variable into oneventfinish\n                            player:setLocalVar('GilToReward', moatCarp * 10 + forestCarp * 15) -- Forces the gil reward to happen AFTER the event like in captures\n                            return quest:progressEvent(305)\n                        end\n                    end\n                end,\n            },\n\n            ['Gallijaux'] = quest:messageName(portSandOriaID.text.GALLIJAUX_HELP_OTHER_BROTHER, 0, 0, 0, 0, true, false),\n\n            ['Ufanne'] =\n            {\n                onTrigger = function(player, npc)\n                    local fishCount = player:getCharVar('carpsTraded')\n                    local cycle     = player:getLocalVar('Cycle')\n\n                    -- NPC cycles dialogue\n                    if cycle == 0 then\n                        player:setLocalVar('Cycle', 1)\n                        return quest:event(309, 1, 0, fishCount)\n                    elseif cycle == 1 then\n                        player:setLocalVar('Cycle', 0)\n                        return quest:event(310)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [305] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:setCharVar('carpsTraded', player:getLocalVar('FishTraded')) -- As per captures this char var persists for the life of the character\n                    npcUtil.giveCurrency(player, 'gil', player:getLocalVar('GilToReward'))\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                end,\n\n                [307] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:setCharVar('carpsTraded', player:getLocalVar('FishTraded')) -- As per captures this char var persists for the life of the character\n                        npcUtil.giveCurrency(player, 'gil', player:getLocalVar('GilToReward'))\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n\n            -- The player may continue to trade carps to Joulet even after obtaining Lu Shang.\n            ['Joulet'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageName(portSandOriaID.text.JOULET_CARP_STATUS, 0, player:getCharVar('carpsTraded'), 0, 0, true, false) -- TODO: The number that Joulet reports increases over time and eventually resets back to 0 before starting to tick back up.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local count        = trade:getItemCount()\n                    local moatCarp     = trade:getItemQty(xi.item.MOAT_CARP_1)\n                    local forestCarp   = trade:getItemQty(xi.item.FOREST_CARP)\n                    local fishCountVar = player:getCharVar('carpsTraded')\n                    local totalFish    = moatCarp + forestCarp + fishCountVar\n\n                    if moatCarp + forestCarp > 0 and moatCarp + forestCarp == count then\n                        player:setLocalVar('FishTraded', totalFish)\n                        player:setLocalVar('GilToReward', moatCarp * 10 + forestCarp * 15) -- Forces the gil reward to happen AFTER the event like in captures\n                        return quest:progressEvent(305)\n                    end\n                end,\n            },\n\n            ['Gallijaux'] = quest:messageName(portSandOriaID.text.GALLIJAUX_HELP_OTHER_BROTHER, 0, 0, 0, 0, true, false),\n\n            ['Ufanne'] =\n            {\n                onTrigger = function(player, npc)\n                    local fishCount = player:getCharVar('carpsTraded')\n                    local cycle     = player:getLocalVar('Cycle')\n\n                    -- NPC cycles dialogue\n                    if cycle == 0 then\n                        player:setLocalVar('Cycle', 1)\n                        return quest:event(309, 1, 0, fishCount)\n                    elseif cycle == 1 then\n                        player:setLocalVar('Cycle', 0)\n                        return quest:event(310)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [305] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:setCharVar('carpsTraded', player:getLocalVar('FishTraded'))  -- As per captures this char var persists for the life of the character\n                    npcUtil.giveCurrency(player, 'gil', player:getLocalVar('GilToReward'))\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Dismayed_Customer.lua"]={["Path"]="scripts/quests/sandoria/The_Dismayed_Customer.lua",["SHA256"]="fdd78b8d9c614cfef118e5de4659da533f835479860db255f5d4093f9324459b",["Text"]="-----------------------------------\n-- The Dismayed Customer\n-----------------------------------\n-- Log ID: 0, Quest ID: 6\n-- Gulemont : !pos -69 -5 -38 232\n-- qm1      : !pos -453 -20 -230 100\n-- qm2      : !pos -550 -0 -542 100\n-- qm3      : !pos -399 -10 -438 100\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_DISMAYED_CUSTOMER)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    gil = 560,\n    title = xi.title.LOST_FOUND_OFFICER,\n}\n\nlocal function handleQm(player, qmNumber)\n    if quest:getVar(player, 'Stage') == qmNumber then\n        quest:setVar(player, 'Stage', 0)\n        return quest:keyItem(xi.keyItem.GULEMONTS_DOCUMENT)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_TASTE_FOR_MEAT)\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Gulemont'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(605)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [605] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Stage', math.randomInt(1, 3))\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Gulemont'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.GULEMONTS_DOCUMENT) then\n                        return quest:progressEvent(607)\n                    else\n                        return quest:progressEvent(606)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [607] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.GULEMONTS_DOCUMENT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    return handleQm(player, 1)\n                end,\n            },\n\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    return handleQm(player, 2)\n                end,\n            },\n\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    return handleQm(player, 3)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
